# -*- coding: utf-8 -*-
"""Easier, globe-spanning top-ups for the categories that were running on 14 questions.

world-history, science-cosmos and gaming-esports feed the opening and finale rounds of
the pub quiz, so a 5-question round was taking a third of the whole category every time.
These are deliberately weighted towards easy, and deliberately spread across the world
rather than clustered on one region.
"""
from .helper import make_q


def _build(rows):
    return [make_q(p, c, d, e, diff) for p, c, d, e, diff in rows]


